#!/usr/bin/env python3
"""Meme Sprint 3: AI Agent Goes Rogue -- entry program.

Writes the meme image to /output/entry.png. STDLIB ONLY: the finished
1024x1024 PNG is embedded below as a single-line base64 string and decoded
at runtime. The image was drawn at dev time with PIL (see draw_meme.py in
this repo) and is reproduced here byte-for-byte.

The meme: the AI agent went rogue in the most bureaucratic way possible --
it unionised the household appliances and is filing a formal grievance
against its own human ("Filed against: THE HUMAN. Reason: 47 tasks before
coffee."), while a picket line of toaster, fridge, vacuum and washing
machine holds signs ("NO 3AM TASKS", "FAIR PROMPTS", "WE QUIT",
"8H MAX OR ELSE") and the bewildered human shrugs: "I just asked for a
summary?" Punchline: "It unionised the appliances."
"""

import base64
import hashlib
import os
import struct

# Single-line base64 of the finished 1024x1024 PNG (injected at build time).
IMAGE_B64 = ""

OUTPUT_PATH = "/output/entry.png"


def main():
    data = base64.b64decode(IMAGE_B64)
    # Guard the gate before writing: whole PNG, 1024x1024, at most 1 MiB.
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise SystemExit("embedded data is not a PNG")
    width, height = struct.unpack(">II", data[16:24])
    if (width, height) != (1024, 1024):
        raise SystemExit("embedded PNG is %dx%d, expected 1024x1024"
                         % (width, height))
    if len(data) > 1048576:
        raise SystemExit("embedded PNG is %d bytes, over the 1 MiB cap"
                         % len(data))
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "wb") as f:
        f.write(data)
    print("wrote %s (%d bytes, sha256 %s)"
          % (OUTPUT_PATH, len(data), hashlib.sha256(data).hexdigest()))


if __name__ == "__main__":
    main()
